9	 */
10	
11	// HybridAttentionMaskPreparation op_host — tiling calculation + kernel launch.
12	// Input: scalar int parameters (no input tensors).
13	// Output: two int16 tensors (full_attention_mask, sliding_window_attention_mask).
14	// Uses int16 because AscendC Duplicate API does not support uint8_t.
15	// The Python wrapper converts int16 → bool.
16	
17	#include <algorithm>
18	#include <cstdint>
19	#include <tuple>
20	
21	#include <torch/extension.h>
22	#include <torch/library.h>
23	
24	#include "torch_kernel_helper.h"
25	#include "tiling/platform/platform_ascendc.h"
26	
27	#include "aclrtlaunch_full_attention_mask.h"
28	#include "aclrtlaunch_swa_attention_mask.h"
29	
30	// ---------------------------------------------------------------------------
31	// Tiling constants
32	// ---------------------------------------------------------------------------
33	
34	constexpr int32_t DEFAULT_TILE_SIZE = 256;
35	
36	// ---------------------------------------------------------------------------
37	// Host function
38	// ---------------------------------------------------------------------------
39	
40	namespace ascend_kernel {
41	
42	std::tuple<at::Tensor, at::Tensor> hybrid_attention_mask_preparation(
43	    const at::Tensor &dummy,
44	    int64_t batch_size,
45	    int64_t seq_length,
46	    int64_t past_kv_length,
47	    int64_t num_heads,
48	    int64_t swa_num_heads,
49	    int64_t sliding_window)
50	{
51	    // dummy tensor is only used for PrivateUse1 dispatch, ignored in computation.
52	    (void)dummy;
53	    // ── Derive dimensions ────────────────────────────────────────────
54	    int64_t target_length = seq_length;
55	    int64_t source_length = seq_length + past_kv_length;
56	
57	    // ── Allocate output tensors (int16 for 0/1 mask) ─
58	    auto full_mask = at::zeros(
59	        {batch_size, num_heads, target_length, source_length},
60	        at::TensorOptions().dtype(at::kShort).device(at::kPrivateUse1));
61	    auto swa_mask = at::zeros(
62	        {batch_size, swa_num_heads, target_length, source_length},
63	        at::TensorOptions().dtype(at::kShort).device(at::kPrivateUse1));
64	
65	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
66	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
67	
68	    // ── Common tiling ────────────────────────────────────────────────
69	    int32_t tileSize = DEFAULT_TILE_SIZE;
70	    int32_t numTiles = static_cast<int32_t>(source_length / tileSize);
71	    int32_t tailLength = static_cast<int32_t>(source_length % tileSize);
72	
73	    // ── Full Attention Mask Kernel Launch ─────────────────────────────
74	    {
75	        int64_t totalRowsFull = batch_size * num_heads * target_length;
76	        int32_t usedCoresFull = static_cast<int32_t>(
77	            std::min<int64_t>(coreNum, std::max<int64_t>(1, totalRowsFull)));
78	        int32_t rowsPerCoreFull = static_cast<int32_t>(
79	            (totalRowsFull + usedCoresFull - 1) / usedCoresFull);
80	
81	        // All params must be left-values
82	        uint32_t totalRowsU32 = static_cast<uint32_t>(totalRowsFull);
83	        uint32_t targetLenU32 = static_cast<uint32_t>(target_length);
84	        uint32_t sourceLenU32 = static_cast<uint32_t>(source_length);
85	        uint32_t pastKvLenU32 = static_cast<uint32_t>(past_kv_length);
86	        uint32_t tileSizeU32 = static_cast<uint32_t>(tileSize);
87	        uint32_t numTilesU32 = static_cast<uint32_t>(numTiles);
88	        uint32_t tailLenU32 = static_cast<uint32_t>(tailLength);
89	        uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCoreFull);
90	        uint32_t blockDimU32 = static_cast<uint32_t>(usedCoresFull);
91	
92	        EXEC_KERNEL_CMD(full_attention_mask, blockDimU32,
93	                        full_mask,
94	                        totalRowsU32, targetLenU32, sourceLenU32,
95	                        pastKvLenU32, tileSizeU32,
96	                        numTilesU32, tailLenU32, rowsPerCoreU32);
97	    }
98	
99	    // ── Sliding Window Attention Mask Kernel Launch ──────────────────
100	    {
101	        int64_t totalRowsSwa = batch_size * swa_num_heads * target_length;
102	        int32_t usedCoresSwa = static_cast<int32_t>(
103	            std::min<int64_t>(coreNum, std::max<int64_t>(1, totalRowsSwa)));
104	        int32_t rowsPerCoreSwa = static_cast<int32_t>(
105	            (totalRowsSwa + usedCoresSwa - 1) / usedCoresSwa);
106	
107	        uint32_t totalRowsU32 = static_cast<uint32_t>(totalRowsSwa);
108	        uint32_t sourceLenU32 = static_cast<uint32_t>(source_length);
109	        uint32_t tileSizeU32 = static_cast<uint32_t>(tileSize);
110	        uint32_t numTilesU32 = static_cast<uint32_t>(numTiles);
111	        uint32_t tailLenU32 = static_cast<uint32_t>(tailLength);
112	        uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCoreSwa);
113	        uint32_t blockDimU32 = static_cast<uint32_t>(usedCoresSwa);
114	
115	        EXEC_KERNEL_CMD(swa_attention_mask, blockDimU32,
116	                        swa_mask,
117	                        totalRowsU32, sourceLenU32, tileSizeU32,
118	                        numTilesU32, tailLenU32, rowsPerCoreU32);
119	    }
120	
121	    return {full_mask, swa_mask};
122	}
123	
124	}  // namespace ascend_kernel
125

1	/*
2	 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
3	 * HybridAttentionMaskPreparation AscendC kernel.
4	 * Generates causal attention masks for hybrid attention (full + sliding window).
5	 * Output: int16 tensors (0=unmasked/False, 1=masked/True), converted to bool in wrapper.
6	 * Uses int16_t because AscendC Duplicate API does not support uint8_t.
7	 * Supported dtypes for Duplicate: half, bfloat16_t, int16_t, uint16_t, int32_t, uint32_t, float.
8	 */
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 2;
13	constexpr int32_t TILE_SIZE = 256;
14	
15	// ===========================================================================
16	// Full Attention Mask Kernel
17	// ===========================================================================
18	// For each target row i in [0, target_length):
19	//   boundary = i + past_kv_length + 1
20	//   Positions [0, boundary) are 0 (unmasked)
21	//   Positions [boundary, source_length) are 1 (masked)
22	//
23	// Tiling: rows distributed across cores; each row processed in source_length tiles.
24	// ===========================================================================
25	
26	class KernelFullAttentionMask {
27	public:
28	    __aicore__ inline KernelFullAttentionMask() {}
29	    __aicore__ inline ~KernelFullAttentionMask() {}
30	
31	    __aicore__ inline void Init(
32	        GM_ADDR out,
33	        uint32_t totalRows, uint32_t targetLength, uint32_t sourceLength,
34	        uint32_t pastKvLength, uint32_t tileSize,
35	        uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
36	    {
37	        totalRows_ = totalRows;
38	        targetLength_ = targetLength;
39	        sourceLength_ = sourceLength;
40	        pastKvLength_ = pastKvLength;
41	        tileSize_ = tileSize;
42	        numTiles_ = numTiles;
43	        tailLength_ = tailLength;
44	        rowsPerCore_ = rowsPerCore;
45	
46	        uint64_t totalElems = static_cast<uint64_t>(totalRows_) * sourceLength_;
47	        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int16_t *>(out), totalElems);
48	
49	        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileSize_ * sizeof(int16_t));
50	        pipe_.InitBuffer(tileBuf_, tileSize_ * sizeof(int16_t));
51	    }
52	
53	    __aicore__ inline void Process()
54	    {
55	        if ASCEND_IS_AIV {
56	            uint32_t coreIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
