{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * HybridAttentionMaskPreparation AscendC kernel.
 * Generates causal attention masks for hybrid attention (full + sliding window).
 * Output: int16 tensors (0=unmasked/False, 1=masked/True), converted to bool in wrapper.
 * Uses int16_t because AscendC Duplicate API does not support uint8_t.
 * Supported dtypes for Duplicate: half, bfloat16_t, int16_t, uint16_t, int32_t, uint32_t, float.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t TILE_SIZE = 256;

// ===========================================================================
// Full Attention Mask Kernel
// ===========================================================================
// For each target row i in [0, target_length):
//   boundary = i + past_kv_length + 1
//   Positions [0, boundary) are 0 (unmasked)
//   Positions [boundary, source_length) are 1 (masked)
//
// Tiling: rows distributed across cores; each row processed in source_length tiles.
// ===========================================================================

class KernelFullAttentionMask {
public:
    __aicore__ inline KernelFullAttentionMask() {}
    __aicore__ inline ~KernelFullAttentionMask() {}

    __aicore__ inline void Init(
        GM_ADDR out,
        uint32_t totalRows, uint32_t targetLength, uint32_t sourceLength,
        uint32_t pastKvLength, uint32_t tileSize,
        uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
    {
        totalRows_ = totalRows;
        targetLength_ = targetLength;
        sourceLength_ = sourceLength;
        pastKvLength_ = pastKvLength;
        tileSize_ = tileSize;
        numTiles_ = numTiles;
        tailLength_ = tailLength;
        rowsPerCore_ = rowsPerCore;

        uint64_t totalElems = static_cast<uint64_t>(totalRows_) * sourceLength_;
        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int16_t *>(out), totalElems);

        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileSize_ * sizeof(int16_t));
        pipe_.InitBuffer(tileBuf_, tileSize_ * sizeof(int16_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
            uint32_t rowStart = coreIdx * rowsPerCore_;
            uint32_t rowEnd = rowStart + rowsPerCore_;
            if (rowEnd > totalRows_) { rowEnd = totalRows_; }

            for (uint32_t row = rowStart; row < rowEnd; ++row) {
                ProcessRow(row);
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(uint32_t rowIdx)
    {
        uint32_t i = rowIdx % targetLength_;
        uint32_t boundary = i + pastKvLength_ + 1;

        uint64_t rowBase = static_cast<uint64_t>(rowIdx) * sourceLength_;
        uint32_t totalTiles = numTiles_ + (tailLength_ > 0 ? 1 : 0);

        for (uint32_t t = 0; t < totalTiles; ++t) {
            uint32_t curLen = (t < numTiles_) ? tileSize_ : tailLength_;
            if (curLen == 0) break;
            Compute(t, curLen, boundary);
            CopyOut(t, rowBase, curLen);
        }
    }

    __aicore__ inline void Compute(uint32_t tileIdx, uint32_t curLen, uint32_t boundary)
    {
        uint32_t tileStart = tileIdx * tileSize_;
        AscendC::LocalTensor<int16_t> tile = tileBuf_.Get<int16_t>();

        if (tileStart >= boundary) {
            // Entire tile in masked region → all 1s
            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(1), curLen);
        } else if (tileStart + curLen <= boundary) {
            // Entire tile before boundary → all 0s
            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(0), curLen);
        } else {
            // Tile contains the boundary → mixed 0/1
            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(0), curLen);
            // Fill [zeroCount, curLen) with 1 using scalar SetValue
            uint32_t zeroCount = boundary - tileStart;
            for (uint32_t k = zeroCount; k < curLen; ++k) {
                tile.SetValue(k, static_cast<int16_t>(1));
            }
        }

        // Barrier: ensure vector engine writes are visible to MTE before DataCopy
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::LocalTensor<int16_t> tileOut = outQueue_.AllocTensor<int16_t>();
        AscendC::DataCopy(tileOut, tile, curLen);
        outQueue_.EnQue(tileOut);
    }

    __aicore__ inline void CopyOut(uint32_t tileIdx, uint64_t rowBase, uint32_t curLen)
    {
        AscendC::LocalTensor<int16_t> src = outQueue_.DeQue<int16_t>();
        AscendC::DataCopyExtParams cp{1, curLen * static_cast<uint32_t>(sizeof(int16_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm_[rowBase + tileIdx * tileSize_], src, cp);
        outQueue_.FreeTensor(src);
    }

private:
    AscendC::GlobalTensor<int16_t> outGm_;
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tileBuf_;
    uint32_t totalRows_, targetLength_, sourceLength_, pastKvLength_;
    uint32_t tileSize_, numTiles_, tailLength_, rowsPerCore_;
};

extern "C" __global__ __aicore__ void full_attention_mask(
    GM_ADDR out,
    uint32_t totalRows, uint32_t targetLength, uint32_t sourceLength,
    uint32_t pastKvLength, uint32_t tileSize,
    uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
{
    KernelFullAttentionMask k;
    k.Init(out, totalRows, targetLength, sourceLength, pastKvLength,
           tileSize, numTiles, tailLength, rowsPerCore);
    k.Process();
}


// ===========================================================================
// Sliding Window Attention Mask Kernel
// ===========================================================================
// All positions are 0 (unmasked/False). Zero-fills the output tensor.
// ===========================================================================

class KernelSwaAttentionMask {
public:
    __aicore__ inline KernelSwaAttentionMask() {}
    __aicore__ inline ~KernelSwaAttentionMask() {}

    __aicore__ inline void Init(
        GM_ADDR out,
        uint32_t totalRows, uint32_t sourceLength, uint32_t tileSize,
        uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
    {
        totalRows_ = totalRows;
        sourceLength_ = sourceLength;
        tileSize_ = tileSize;
        numTiles_ = numTiles;
        tailLength_ = tailLength;
        rowsPerCore_ = rowsPerCore;

        uint64_t totalElems = static_cast<uint64_t>(totalRows_) * sourceLength_;
        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int16_t *>(out), totalElems);

        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileSize_ * sizeof(int16_t));
        pipe_.InitBuffer(zeroBuf_, tileSize_ * sizeof(int16_t));
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            uint32_t coreIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
            uint32_t rowStart = coreIdx * rowsPerCore_;
            uint32_t rowEnd = rowStart + rowsPerCore_;
            if (rowEnd > totalRows_) { rowEnd = totalRows_; }

            for (uint32_t row = rowStart; row < rowEnd; ++row) {
                ProcessRow(row);
            }
        }
    }

private:
    __aicore__ inline void ProcessRow(uint32_t rowIdx)
    {
        uint64_t rowBase = static_cast<uint64_t>(rowIdx) * sourceLength_;
        uint32_t totalTiles = numTiles_ + (tailLength_ > 0 ? 1 : 0);

        for (uint32_t t = 0; t < totalTiles; ++t) {
            uint32_t curLen = (t < numTiles_) ? tileSize_ : tailLength_;
            if (curLen == 0) break;
            ComputeZero(curLen);
            CopyOut(t, rowBase, curLen);
        }
    }

    __aicore__ inline void ComputeZero(uint32_t curLen)
    {
        AscendC::LocalTensor<int16_t> zero = zeroBuf_.Get<int16_t>();
        AscendC::Duplicate<int16_t>(zero, static_cast<int16_t>(0), curLen);

        // Barrier: ensure vector engine writes are visible to MTE before DataCopy
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::LocalTensor<int16_t> tileOut = outQueue_.AllocTensor<int16_t>();
        AscendC::DataCopy(tileOut, zero, curLen);
        outQueue_.EnQue(tileOut);
    }

    __aicore__ inline void CopyOut(uint32_t tileIdx, uint64_t rowBase, uint32_t curLen)
    {
        AscendC::LocalTensor<int16_t> src = outQueue_.DeQue<int16_t>();
        AscendC::DataCopyExtParams cp{1, curLen * static_cast<uint32_t>(sizeof(int16_t)), 0, 0, 0};
        AscendC::DataCopyPad(outGm_[rowBase + tileIdx * tileSize_], src, cp);
        outQueue_.FreeTensor(src);
    }

private:
    AscendC::GlobalTensor<int16_t> outGm_;
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> zeroBuf_;
    uint32_t totalRows_, sourceLength_;
    uint32_t tileSize_, numTiles_, tailLength_, rowsPerCore_;
};

extern "C" __global__ __aicore__ void swa_attention_mask(
    GM_ADDR out,
    uint32_t totalRows, uint32_t sourceLength, uint32_t tileSize,
    uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
{
    KernelSwaAttentionMask k;
    k.Init(out, totalRows, sourceLength, tileSize, numTiles, tailLength, rowsPerCore);
    k.Process();
}
