// HybridAttentionMaskPreparation op_host — tiling calculation + kernel launch.
// Input: scalar int parameters (no input tensors).
// Output: two int16 tensors (full_attention_mask, sliding_window_attention_mask).
// Uses int16 because AscendC Duplicate API does not support uint8_t.
// The Python wrapper converts int16 → bool.

#include <algorithm>
#include <cstdint>
#include <tuple>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_full_attention_mask.h"
#include "aclrtlaunch_swa_attention_mask.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_TILE_SIZE = 256;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor> hybrid_attention_mask_preparation(
    const at::Tensor &dummy,
    int64_t batch_size,
    int64_t seq_length,
    int64_t past_kv_length,
    int64_t num_heads,
    int64_t swa_num_heads,
    int64_t sliding_window)
{
    // dummy tensor is only used for PrivateUse1 dispatch, ignored in computation.
    (void)dummy;
    // ── Derive dimensions ────────────────────────────────────────────
    int64_t target_length = seq_length;
    int64_t source_length = seq_length + past_kv_length;

    // ── Allocate output tensors (int16 for 0/1 mask) ─
    auto full_mask = at::zeros(
        {batch_size, num_heads, target_length, source_length},
        at::TensorOptions().dtype(at::kShort).device(at::kPrivateUse1));
    auto swa_mask = at::zeros(
        {batch_size, swa_num_heads, target_length, source_length},
        at::TensorOptions().dtype(at::kShort).device(at::kPrivateUse1));

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    // ── Common tiling ────────────────────────────────────────────────
    int32_t tileSize = DEFAULT_TILE_SIZE;
    int32_t numTiles = static_cast<int32_t>(source_length / tileSize);
    int32_t tailLength = static_cast<int32_t>(source_length % tileSize);

    // ── Full Attention Mask Kernel Launch ─────────────────────────────
    {
        int64_t totalRowsFull = batch_size * num_heads * target_length;
        int32_t usedCoresFull = static_cast<int32_t>(
            std::min<int64_t>(coreNum, std::max<int64_t>(1, totalRowsFull)));
        int32_t rowsPerCoreFull = static_cast<int32_t>(
            (totalRowsFull + usedCoresFull - 1) / usedCoresFull);

        // All params must be left-values
        uint32_t totalRowsU32 = static_cast<uint32_t>(totalRowsFull);
        uint32_t targetLenU32 = static_cast<uint32_t>(target_length);
        uint32_t sourceLenU32 = static_cast<uint32_t>(source_length);
        uint32_t pastKvLenU32 = static_cast<uint32_t>(past_kv_length);
        uint32_t tileSizeU32 = static_cast<uint32_t>(tileSize);
        uint32_t numTilesU32 = static_cast<uint32_t>(numTiles);
        uint32_t tailLenU32 = static_cast<uint32_t>(tailLength);
        uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCoreFull);
        uint32_t blockDimU32 = static_cast<uint32_t>(usedCoresFull);

        EXEC_KERNEL_CMD(full_attention_mask, blockDimU32,
                        full_mask,
                        totalRowsU32, targetLenU32, sourceLenU32,
                        pastKvLenU32, tileSizeU32,
                        numTilesU32, tailLenU32, rowsPerCoreU32);
    }

    // ── Sliding Window Attention Mask Kernel Launch ──────────────────
    {
        int64_t totalRowsSwa = batch_size * swa_num_heads * target_length;
        int32_t usedCoresSwa = static_cast<int32_t>(
            std::min<int64_t>(coreNum, std::max<int64_t>(1, totalRowsSwa)));
        int32_t rowsPerCoreSwa = static_cast<int32_t>(
            (totalRowsSwa + usedCoresSwa - 1) / usedCoresSwa);

        uint32_t totalRowsU32 = static_cast<uint32_t>(totalRowsSwa);
        uint32_t sourceLenU32 = static_cast<uint32_t>(source_length);
        uint32_t tileSizeU32 = static_cast<uint32_t>(tileSize);
        uint32_t numTilesU32 = static_cast<uint32_t>(numTiles);
        uint32_t tailLenU32 = static_cast<uint32_t>(tailLength);
        uint32_t rowsPerCoreU32 = static_cast<uint32_t>(rowsPerCoreSwa);
        uint32_t blockDimU32 = static_cast<uint32_t>(usedCoresSwa);

        EXEC_KERNEL_CMD(swa_attention_mask, blockDimU32,
                        swa_mask,
                        totalRowsU32, sourceLenU32, tileSizeU32,
                        numTilesU32, tailLenU32, rowsPerCoreU32);
    }

    return {full_mask, swa_mask};
}

}  // namespace ascend_kernel
