15	// ===========================================================================
16	// Full Attention Mask Kernel
17	// ===========================================================================
18	// For each target row i in [0, target_length):
19	//   boundary = i + past_kv_length + 1
20	//   Positions [0, boundary) are 0 (unmasked)
21	//   Positions [boundary, source_length) are 1 (masked)
22	//
23	// Tiling: rows distributed across cores; each row processed in source_length tiles.
24	// ===========================================================================
25	
26	class KernelFullAttentionMask {
27	public:
28	    __aicore__ inline KernelFullAttentionMask() {}
29	    __aicore__ inline ~KernelFullAttentionMask() {}
30	
31	    __aicore__ inline void Init(
32	        GM_ADDR out,
33	        uint32_t totalRows, uint32_t targetLength, uint32_t sourceLength,
34	        uint32_t pastKvLength, uint32_t tileSize,
35	        uint32_t numTiles, uint32_t tailLength, uint32_t rowsPerCore)
36	    {
37	        totalRows_ = totalRows;
38	        targetLength_ = targetLength;
39	        sourceLength_ = sourceLength;
40	        pastKvLength_ = pastKvLength;
41	        tileSize_ = tileSize;
42	        numTiles_ = numTiles;
43	        tailLength_ = tailLength;
44	        rowsPerCore_ = rowsPerCore;
45	
46	        uint64_t totalElems = static_cast<uint64_t>(totalRows_) * sourceLength_;
47	        outGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int16_t *>(out), totalElems);
48	
49	        pipe_.InitBuffer(outQueue_, BUFFER_NUM, tileSize_ * sizeof(int16_t));
50	        pipe_.InitBuffer(tileBuf_, tileSize_ * sizeof(int16_t));
51	    }
52	
53	    __aicore__ inline void Process()
54	    {
55	        if ASCEND_IS_AIV {
56	            uint32_t coreIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
57	            uint32_t rowStart = coreIdx * rowsPerCore_;
58	            uint32_t rowEnd = rowStart + rowsPerCore_;
59	            if (rowEnd > totalRows_) { rowEnd = totalRows_; }
60	
61	            for (uint32_t row = rowStart; row < rowEnd; ++row) {
62	                ProcessRow(row);
63	            }
64	        }
65	    }
66	
67	private:
68	    __aicore__ inline void ProcessRow(uint32_t rowIdx)
69	    {
70	        uint32_t i = rowIdx % targetLength_;
71	        uint32_t boundary = i + pastKvLength_ + 1;
72	
73	        uint64_t rowBase = static_cast<uint64_t>(rowIdx) * sourceLength_;
74	        uint32_t totalTiles = numTiles_ + (tailLength_ > 0 ? 1 : 0);
75	
76	        for (uint32_t t = 0; t < totalTiles; ++t) {
77	            uint32_t curLen = (t < numTiles_) ? tileSize_ : tailLength_;
78	            if (curLen == 0) break;
79	            Compute(t, curLen, boundary);
80	            CopyOut(t, rowBase, curLen);
81	        }
82	    }
83	
84	    __aicore__ inline void Compute(uint32_t tileIdx, uint32_t curLen, uint32_t boundary)
85	    {
86	        uint32_t tileStart = tileIdx * tileSize_;
87	        AscendC::LocalTensor<int16_t> tile = tileBuf_.Get<int16_t>();
88	
89	        if (tileStart >= boundary) {
90	            // Entire tile in masked region → all 1s
91	            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(1), curLen);
92	        } else if (tileStart + curLen <= boundary) {
93	            // Entire tile before boundary → all 0s
94	            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(0), curLen);
95	        } else {
96	            // Tile contains the boundary → mixed 0/1
97	            AscendC::Duplicate<int16_t>(tile, static_cast<int16_t>(0), curLen);
98	            // Fill [zeroCount, curLen) with 1 using scalar SetValue
99	            uint32_t zeroCount = boundary - tileStart;
100	            for (uint32_t k = zeroCount; k < curLen; ++k) {
101	                tile.SetValue(k, static_cast<int16_t>(1));
102	            }
103	        }
104	
105	        // Barrier: ensure vector engine writes are visible to MTE before DataCopy
106	        AscendC::PipeBarrier<PIPE_V>();
107	
108	        AscendC::LocalTensor<int16_t> tileOut = outQueue_.AllocTensor<int16_t>();
109	        AscendC::DataCopy(tileOut, tile, curLen);
110	        outQueue_.EnQue(tileOut);
111	    }
112	
113	    __aicore__ inline void CopyOut(uint32_t tileIdx, uint64_t rowBase, uint32_t curLen)
114	    {
115	        AscendC::LocalTensor<int16_t> src = outQueue_.DeQue<int16_t>();
116	        AscendC::DataCopyExtParams cp{1, curLen * static_cast<uint32_t>(sizeof(int16_t)), 0, 0, 0};
117	        AscendC::DataCopyPad(outGm_[rowBase + tileIdx * tileSize_], src, cp);
118	        outQueue_.FreeTensor(src);
119	    }
