123	    AscendC::TPipe pipe_;
124	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
125	    AscendC::TBuf<AscendC::TPosition::VECCALC> tileBuf_;
126	    uint32_t totalRows_, targetLength_, sourceLength_, pastKvLength_;
127	    uint32_t tileSize_, numTiles_, tailLength_, rowsPerCore_;
128	};
